/**
 * Eventos reais de 2026, um por OS de estrutura da pasta SharePoint "1- ATA E O.S EVENTOS 2026"
 * (Calendário), extraídos em set/2026: nome, data da prova, local, diretor de prova e responsável
 * pela OS (aba TOTAL), os projetos do catálogo com a quantidade de cada aba da OS (mesma
 * consolidação do catálogo: aba → projeto ou variante) e as tendas 5×5/3×3 por local, com
 * fechamentos. "Outros materiais" e estaiamento da OS não entram (não são projetos nem peças do
 * catálogo). Gerado por script; importado por `npm run importar:eventos`.
 */
export type TendaOs = { kit: "5x5" | "3x3" | string; local: string; quantidade: number; fechamentos: number };
export type EventoOs = {
  /** Pasta/arquivo no SharePoint: identifica a importação (não importa duas vezes). */
  arquivo: string;
  /** Data da OS (última modificação do arquivo) — vira a data da reunião de OS. */
  dataOs: string;
  nome: string;
  dataInicio: string;
  dataFim: string;
  /** A OS não tinha data legível: usada a data da OS + 7 dias. */
  dataEstimada: boolean;
  local: string | null;
  diretor: string | null;
  responsavel: string | null;
  /** [nome do projeto no catálogo, quantidade] */
  projetos: Array<[string, number]>;
  tendas: TendaOs[];
};

